-- Phase 70: central production, internal requisitions and lot-level network supply.
-- Extends the canonical Phase 16 inventory/recipes/transfers and Phase 47 lots/batches.
-- No inventory balance is changed outside the official inventory_movements ledger functions below.
-- quality: allow-nonconcurrent-index reason=new-empty-phase70-tables
create schema if not exists central_production_private;
revoke all on schema central_production_private from public,anon,authenticated;
grant usage on schema central_production_private to service_role;

alter table public.plans add column if not exists central_production_enabled boolean not null default false,add column if not exists internal_requisitions_enabled boolean not null default false,add column if not exists interstore_transfers_enabled boolean not null default false,add column if not exists production_batch_traceability_enabled boolean not null default false,add column if not exists production_planning_enabled boolean not null default false;
alter table public.store_feature_flags add column if not exists central_production_enabled boolean not null default true,add column if not exists internal_requisitions_enabled boolean not null default true,add column if not exists interstore_transfers_enabled boolean not null default true,add column if not exists production_batch_traceability_enabled boolean not null default true,add column if not exists production_planning_enabled boolean not null default true;

alter table public.inventory_items add column if not exists production_item_kind text,add column if not exists visibility text not null default 'operational',add column if not exists shelf_life_hours integer,add column if not exists after_opening_shelf_life_hours integer;
alter table public.inventory_items drop constraint if exists inventory_items_production_item_kind_check;
alter table public.inventory_items add constraint inventory_items_production_item_kind_check check(production_item_kind is null or production_item_kind in('ingredient','semi_finished','finished_good','prep_component'));
alter table public.inventory_items drop constraint if exists inventory_items_visibility_check;
alter table public.inventory_items add constraint inventory_items_visibility_check check(visibility in('operational','internal_only','menu_visible'));
alter table public.inventory_items add constraint inventory_items_shelf_life_check check((shelf_life_hours is null or shelf_life_hours>0) and(after_opening_shelf_life_hours is null or after_opening_shelf_life_hours>0));
alter table public.inventory_recipes add column if not exists recipe_type text not null default 'sales_recipe',add column if not exists recipe_version integer not null default 1;
alter table public.inventory_recipes drop constraint if exists inventory_recipes_recipe_type_check;
alter table public.inventory_recipes add constraint inventory_recipes_recipe_type_check check(recipe_type in('sales_recipe','production_recipe','intermediate_recipe'));

alter table public.inventory_locations drop constraint if exists inventory_locations_location_type_check;
alter table public.inventory_locations add constraint inventory_locations_location_type_check check(location_type in('freezer','cooler','dry_storage','cold_room','production','in_transit','other'));
alter table public.inventory_lots drop constraint if exists inventory_lots_status_check;
alter table public.inventory_lots add constraint inventory_lots_status_check check(status in('active','released','quarantined','blocked','depleted','expired','recalled','discarded'));

create table public.production_units(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,
 store_id uuid references public.establishments(id) on delete set null,inventory_establishment_id uuid not null references public.establishments(id) on delete restrict,warehouse_id uuid,
 unit_type text not null check(unit_type in('central_kitchen','commissary','internal_factory','prep_center','store_production','warehouse_with_production')),
 name text not null,status text not null default 'active' check(status in('active','inactive','maintenance','outage')),timezone text not null default 'America/Sao_Paulo',active boolean not null default true,
 capacity_resource_refs jsonb not null default '[]',settings jsonb not null default '{}',created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,name)
);
comment on column public.production_units.inventory_establishment_id is 'Internal establishments may back inventory without being a public/open store.';
create table public.production_recipe_profiles(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,production_unit_id uuid references public.production_units(id) on delete set null,
 product_id uuid references public.products(id) on delete set null,output_item_id uuid not null references public.inventory_items(id) on delete restrict,recipe_type text not null check(recipe_type in('production_recipe','intermediate_recipe')),
 version integer not null default 1,expected_yield numeric(18,4) not null check(expected_yield>0),yield_unit text not null,waste_expectation_percent numeric(7,3) not null default 0 check(waste_expectation_percent>=0),
 consumption_mode text not null default 'consume_on_completion' check(consumption_mode in('consume_on_start','consume_on_completion','step_based','manual_issue')),
 shelf_life_hours integer check(shelf_life_hours is null or shelf_life_hours>0),after_opening_shelf_life_hours integer check(after_opening_shelf_life_hours is null or after_opening_shelf_life_hours>0),
 processing_steps jsonb not null default '[]',quality_requirements jsonb not null default '[]',status text not null default 'draft' check(status in('draft','active','retired')),
 created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,output_item_id,version)
);
comment on table public.production_recipe_profiles is 'Metadata/version around canonical inventory_recipes; does not duplicate recipe components.';
create table public.production_recipe_outputs(id uuid primary key default gen_random_uuid(),recipe_id uuid not null references public.production_recipe_profiles(id) on delete cascade,inventory_item_id uuid not null references public.inventory_items(id) on delete restrict,quantity numeric(18,4) not null check(quantity>0),unit text not null,output_type text not null default 'primary' check(output_type in('primary','byproduct')),cost_allocation_percent numeric(7,3) check(cost_allocation_percent is null or cost_allocation_percent between 0 and 100),unique(recipe_id,inventory_item_id));
create table public.production_batch_policies(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,recipe_id uuid not null references public.production_recipe_profiles(id) on delete cascade,min_batch numeric(18,4) not null default 0,standard_batch numeric(18,4) not null check(standard_batch>0),max_batch numeric(18,4) not null check(max_batch>0),rounding_rule text not null default 'up' check(rounding_rule in('up','nearest','down')),pack_size numeric(18,4) not null default 1 check(pack_size>0),active boolean not null default true,unique(recipe_id),check(max_batch>=standard_batch and standard_batch>=min_batch));

create table public.production_orders(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,production_unit_id uuid not null references public.production_units(id) on delete restrict,recipe_id uuid not null references public.production_recipe_profiles(id) on delete restrict,
 order_number bigint generated always as identity,planned_quantity numeric(18,4) not null check(planned_quantity>0),actual_quantity numeric(18,4),unit text not null,status text not null default 'draft' check(status in('draft','planned','released','in_progress','paused','completed','cancelled','partially_completed')),
 planned_start_at timestamptz not null,planned_end_at timestamptz,started_at timestamptz,completed_at timestamptz,owner_user_id uuid references auth.users(id),source_type text not null default 'manual' check(source_type in('manual','store_requisition','forecast','replenishment','campaign','opening_stock','custom')),source_id uuid,priority integer not null default 50 check(priority between 0 and 100),
 forecast_version_id uuid,capacity_snapshot jsonb not null default '{}',planning_reasons jsonb not null default '[]',released_by uuid references auth.users(id),released_at timestamptz,cancel_reason text,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create table public.production_material_requirements(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,production_order_id uuid not null references public.production_orders(id) on delete cascade,inventory_item_id uuid not null references public.inventory_items(id) on delete restrict,required_quantity numeric(18,4) not null check(required_quantity>0),reserved_quantity numeric(18,4) not null default 0 check(reserved_quantity>=0),issued_quantity numeric(18,4) not null default 0 check(issued_quantity>=0),unit text not null,conversion_factor numeric(18,6) not null default 1 check(conversion_factor>0),shortage_quantity numeric(18,4) not null default 0 check(shortage_quantity>=0),availability_snapshot jsonb not null default '{}',unique(production_order_id,inventory_item_id));
create table public.inventory_reservations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,establishment_id uuid not null references public.establishments(id) on delete cascade,inventory_item_id uuid not null references public.inventory_items(id) on delete restrict,lot_id uuid references public.inventory_lots(id) on delete restrict,source_type text not null check(source_type in('production_order','internal_requisition','inventory_transfer')),source_id uuid not null,quantity numeric(18,4) not null check(quantity>0),released_quantity numeric(18,4) not null default 0 check(released_quantity>=0),status text not null default 'active' check(status in('active','partially_consumed','consumed','released','cancelled')),expires_at timestamptz,idempotency_key text not null,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,idempotency_key));
create table public.production_material_issues(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,production_order_id uuid not null references public.production_orders(id) on delete restrict,production_batch_id uuid references public.production_batches(id) on delete restrict,inventory_item_id uuid not null references public.inventory_items(id) on delete restrict,lot_id uuid not null references public.inventory_lots(id) on delete restrict,quantity numeric(18,4) not null check(quantity>0),unit text not null,inventory_movement_id uuid not null unique references public.inventory_movements(id) on delete restrict,idempotency_key text not null,issued_by uuid references auth.users(id),issued_at timestamptz not null default now(),unique(organization_id,idempotency_key));

alter table public.production_batches add column if not exists production_order_id uuid references public.production_orders(id) on delete restrict,add column if not exists batch_number text,add column if not exists recipe_version integer not null default 1,add column if not exists planned_quantity numeric(18,4),add column if not exists actual_quantity numeric(18,4),add column if not exists quality_status text not null default 'not_required',add column if not exists expected_yield numeric(18,4),add column if not exists actual_yield numeric(18,4),add column if not exists yield_variance numeric(18,4),add column if not exists waste_quantity numeric(18,4) not null default 0,add column if not exists cost_snapshot jsonb not null default '{}',add column if not exists total_cost_cents bigint,add column if not exists cost_per_unit_cents numeric(18,4),add column if not exists cost_locked_at timestamptz;
alter table public.production_batches drop constraint if exists production_batches_status_check;
alter table public.production_batches add constraint production_batches_status_check check(status in('planned','released','in_progress','paused','completed','blocked','discarded','partially_completed','cancelled'));
alter table public.production_batches add constraint production_batches_quality_status_check check(quality_status in('not_required','pending','passed','warning','quarantined','released','rejected'));
create unique index production_batches_readable_number on public.production_batches(organization_id,batch_number) where batch_number is not null;
alter table public.production_batch_inputs add column if not exists material_issue_id uuid references public.production_material_issues(id) on delete set null;
create table public.production_batch_quality_checks(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,production_batch_id uuid not null references public.production_batches(id) on delete cascade,check_type text not null,configured_rule jsonb not null default '{}',observed_value jsonb not null default '{}',result text not null check(result in('pass','warning','fail','not_applicable')),quality_nonconformity_id uuid references public.quality_nonconformities(id) on delete set null,checked_by uuid references auth.users(id),checked_at timestamptz not null default now(),notes text);
create table public.production_waste_records(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,production_order_id uuid not null references public.production_orders(id) on delete restrict,production_batch_id uuid references public.production_batches(id) on delete restrict,inventory_item_id uuid not null references public.inventory_items(id) on delete restrict,lot_id uuid references public.inventory_lots(id) on delete restrict,quantity numeric(18,4) not null check(quantity>0),unit text not null,reason text not null check(reason in('trim','process_loss','quality_reject','spill','overproduction','expiration','other')),movement_id uuid not null unique references public.inventory_movements(id) on delete restrict,notes text,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table public.production_cost_snapshots(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,production_batch_id uuid not null unique references public.production_batches(id) on delete restrict,material_cents bigint not null default 0,packaging_cents bigint not null default 0,direct_labor_estimate_cents bigint not null default 0,overhead_estimate_cents bigint not null default 0,total_cents bigint not null,cost_per_unit_cents numeric(18,4) not null,valuation_method text not null default 'weighted_material_plus_configured_addons',components jsonb not null default '[]',locked_at timestamptz not null default now(),locked_by uuid references auth.users(id),check(total_cents>=0));

create table public.internal_requisitions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,requesting_store_id uuid not null references public.establishments(id) on delete restrict,supplying_unit_id uuid references public.production_units(id) on delete restrict,requisition_number bigint generated always as identity,requested_for_date date not null,status text not null default 'draft' check(status in('draft','submitted','approved','partially_allocated','allocated','fulfilled','cancelled')),priority integer not null default 50 check(priority between 0 and 100),late_request boolean not null default false,cutoff_snapshot jsonb not null default '{}',created_by uuid references auth.users(id),approved_by uuid references auth.users(id),approved_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.internal_requisition_items(id uuid primary key default gen_random_uuid(),requisition_id uuid not null references public.internal_requisitions(id) on delete cascade,item_id uuid not null references public.inventory_items(id) on delete restrict,requested_quantity numeric(18,4) not null check(requested_quantity>0),approved_quantity numeric(18,4),allocated_quantity numeric(18,4) not null default 0,fulfilled_quantity numeric(18,4) not null default 0,unit text not null,notes text,warning_code text,unique(requisition_id,item_id));
create table public.production_allocations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,requisition_item_id uuid not null references public.internal_requisition_items(id) on delete restrict,production_order_id uuid references public.production_orders(id) on delete set null,inventory_reservation_id uuid references public.inventory_reservations(id) on delete set null,policy text not null check(policy in('proportional','priority_store','first_approved','manual','minimum_guarantee')),requested_quantity numeric(18,4) not null,allocated_quantity numeric(18,4) not null,shortfall_quantity numeric(18,4) not null default 0,allocation_preview jsonb not null default '{}',allocated_by uuid references auth.users(id),allocated_at timestamptz not null default now());
create table public.internal_supply_links(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,supplying_unit_id uuid not null references public.production_units(id) on delete cascade,receiving_store_id uuid not null references public.establishments(id) on delete cascade,inventory_item_id uuid references public.inventory_items(id) on delete cascade,category_scope text,priority integer not null default 100,active boolean not null default true,failover_policy text not null default 'suggest_only' check(failover_policy in('suggest_only','manual','policy_approved')),created_at timestamptz not null default now(),check(inventory_item_id is not null or category_scope is not null));

alter table public.inventory_transfers drop constraint if exists inventory_transfers_status_check;
alter table public.inventory_transfers add constraint inventory_transfers_status_check check(status in('draft','pending','approved','picking','packed','dispatched','in_transit','partially_received','received','cancelled','discrepancy_review'));
alter table public.inventory_transfers add column if not exists transfer_number text,add column if not exists source_production_unit_id uuid references public.production_units(id) on delete set null,add column if not exists destination_production_unit_id uuid references public.production_units(id) on delete set null,add column if not exists approved_by uuid references auth.users(id),add column if not exists approved_at timestamptz,add column if not exists packed_at timestamptz,add column if not exists dispatched_at timestamptz,add column if not exists expected_arrival_at timestamptz,add column if not exists transport_type text,add column if not exists carrier_reference text,add column if not exists fulfillment_type text not null default 'internal_transfer',add column if not exists valuation_method text not null default 'cost',add column if not exists valuation_snapshot jsonb not null default '{}',add column if not exists in_transit_location_id uuid references public.inventory_locations(id) on delete set null;
alter table public.inventory_transfers add constraint inventory_transfers_fulfillment_check check(fulfillment_type='internal_transfer');
alter table public.inventory_transfers add constraint inventory_transfers_valuation_check check(valuation_method in('cost','standard_cost','cost_plus','managerial_transfer_price'));
create unique index inventory_transfer_number_uq on public.inventory_transfers(organization_id,transfer_number) where transfer_number is not null;
alter table public.inventory_transfer_items add column if not exists requested_quantity numeric(18,4),add column if not exists unit text,add column if not exists picking_status text not null default 'pending',add column if not exists condition_status text;
update public.inventory_transfer_items set requested_quantity=quantity where requested_quantity is null;
alter table public.inventory_transfer_items alter column requested_quantity set not null;
create table public.inventory_transfer_item_lots(id uuid primary key default gen_random_uuid(),transfer_item_id uuid not null references public.inventory_transfer_items(id) on delete cascade,source_lot_id uuid not null references public.inventory_lots(id) on delete restrict,destination_lot_id uuid references public.inventory_lots(id) on delete restrict,quantity_requested numeric(18,4) not null check(quantity_requested>0),quantity_sent numeric(18,4) not null default 0,quantity_received numeric(18,4) not null default 0,quantity_rejected numeric(18,4) not null default 0,unit text not null,unique(transfer_item_id,source_lot_id));
create table public.transfer_packages(id uuid primary key default gen_random_uuid(),transfer_id uuid not null references public.inventory_transfers(id) on delete cascade,package_number text not null,package_type text,weight numeric(18,4),seal_code text,status text not null default 'open' check(status in('open','sealed','dispatched','received','damaged')),label_snapshot jsonb not null default '{}',unique(transfer_id,package_number));
create table public.inventory_transfer_transit_balances(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,transfer_id uuid not null references public.inventory_transfers(id) on delete cascade,transfer_item_lot_id uuid not null references public.inventory_transfer_item_lots(id) on delete restrict,inventory_item_id uuid not null references public.inventory_items(id) on delete restrict,lot_id uuid not null references public.inventory_lots(id) on delete restrict,quantity numeric(18,4) not null check(quantity>=0),unit text not null,location_id uuid not null references public.inventory_locations(id) on delete restrict,updated_at timestamptz not null default now(),unique(transfer_item_lot_id));
create table public.transfer_receipts(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,transfer_id uuid not null references public.inventory_transfers(id) on delete restrict,destination_establishment_id uuid not null references public.establishments(id) on delete restrict,result text not null check(result in('accepted','partial','rejected','damaged','missing','excess')),status text not null default 'draft' check(status in('draft','confirmed','reversed')),received_by uuid references auth.users(id),received_at timestamptz,idempotency_key text not null,notes text,created_at timestamptz not null default now(),unique(organization_id,idempotency_key));
create table public.transfer_receipt_items(id uuid primary key default gen_random_uuid(),receipt_id uuid not null references public.transfer_receipts(id) on delete cascade,transfer_item_lot_id uuid not null references public.inventory_transfer_item_lots(id) on delete restrict,quantity_received numeric(18,4) not null default 0,quantity_rejected numeric(18,4) not null default 0,condition text not null check(condition in('accepted','damaged','missing','excess','wrong_item','wrong_lot','expired','temperature_issue')),temperature numeric(7,2),quality_check_id uuid references public.receiving_quality_checks(id) on delete set null,destination_movement_id uuid references public.inventory_movements(id) on delete set null,destination_lot_id uuid references public.inventory_lots(id) on delete set null);
create table public.transfer_discrepancies(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,transfer_id uuid not null references public.inventory_transfers(id) on delete restrict,receipt_item_id uuid references public.transfer_receipt_items(id) on delete set null,inventory_item_id uuid references public.inventory_items(id) on delete restrict,lot_id uuid references public.inventory_lots(id) on delete restrict,discrepancy_type text not null check(discrepancy_type in('shortage','excess','damaged','wrong_item','wrong_lot','expired','temperature_issue','other')),sent_quantity numeric(18,4) not null default 0,received_quantity numeric(18,4) not null default 0,difference numeric(18,4) not null,reason text,status text not null default 'open' check(status in('open','investigating','accepted','return_requested','resolved','dismissed')),owner_user_id uuid references auth.users(id),quality_nonconformity_id uuid references public.quality_nonconformities(id) on delete set null,resolved_by uuid references auth.users(id),resolved_at timestamptz,created_at timestamptz not null default now());
create table public.internal_transfer_returns(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,transfer_id uuid not null references public.inventory_transfers(id) on delete restrict,source_store_id uuid not null references public.establishments(id) on delete restrict,destination_establishment_id uuid not null references public.establishments(id) on delete restrict,status text not null default 'requested' check(status in('requested','approved','dispatched','received','cancelled')),reason text not null check(reason in('excess','quality_issue','wrong_delivery','nearing_expiration','other')),requested_by uuid references auth.users(id),approved_by uuid references auth.users(id),requested_at timestamptz not null default now(),approved_at timestamptz,dispatched_at timestamptz,received_at timestamptz);
create table public.internal_transfer_return_items(id uuid primary key default gen_random_uuid(),return_id uuid not null references public.internal_transfer_returns(id) on delete cascade,inventory_item_id uuid not null references public.inventory_items(id) on delete restrict,lot_id uuid not null references public.inventory_lots(id) on delete restrict,quantity numeric(18,4) not null check(quantity>0),unit text not null,outbound_movement_id uuid references public.inventory_movements(id),inbound_movement_id uuid references public.inventory_movements(id));

create table public.production_planning_runs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,production_unit_id uuid not null references public.production_units(id) on delete cascade,status text not null default 'queued' check(status in('queued','running','completed','failed','cancelled')),forecast_version_id uuid,inputs_snapshot jsonb not null default '{}',suggestions jsonb not null default '[]',warnings jsonb not null default '[]',started_at timestamptz,completed_at timestamptz,error text,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table public.production_audit_events(id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id) on delete cascade,production_unit_id uuid references public.production_units(id) on delete set null,store_id uuid references public.establishments(id) on delete set null,actor_user_id uuid references auth.users(id) on delete set null,event_type text not null,entity_type text not null,entity_id uuid,reason text,before_state jsonb,after_state jsonb,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create table public.production_observability_hourly(organization_id uuid not null references public.organizations(id) on delete cascade,bucket_at timestamptz not null,metric_key text not null,metric_value numeric not null default 0,dimensions jsonb not null default '{}',primary key(organization_id,bucket_at,metric_key));
create table public.central_production_member_permissions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,permissions text[] not null default '{}',production_unit_ids uuid[] not null default '{}',store_ids uuid[] not null default '{}',active boolean not null default true,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,user_id));
alter table public.central_production_member_permissions add constraint central_production_permissions_known check(permissions <@ array['central_production:view','central_production:plan','central_production:create_order','central_production:release_order','central_production:complete_order','central_production:view_cost','central_production:manage_requisitions','central_production:allocate','central_production:manage_transfers','central_production:dispatch','central_production:receive','central_production:manage_discrepancies','central_production:view_network','central_production:manage_settings']::text[]);

create index production_orders_board_idx on public.production_orders(organization_id,production_unit_id,status,planned_start_at,priority desc);
create index production_requirements_order_idx on public.production_material_requirements(production_order_id,inventory_item_id);
create index inventory_reservations_item_idx on public.inventory_reservations(establishment_id,inventory_item_id,status,expires_at);
create index internal_requisitions_store_idx on public.internal_requisitions(organization_id,requesting_store_id,status,requested_for_date);
create index transfer_lots_lot_idx on public.inventory_transfer_item_lots(source_lot_id);
create index transfer_receipts_transfer_idx on public.transfer_receipts(transfer_id,status,created_at desc);
create index transfer_discrepancies_open_idx on public.transfer_discrepancies(organization_id,status,created_at desc) where status in('open','investigating','return_requested');
create index production_audit_scope_idx on public.production_audit_events(organization_id,production_unit_id,created_at desc);
create index production_batches_order_idx on public.production_batches(production_order_id,production_date desc) where production_order_id is not null;
create index inventory_transfers_source_status_idx on public.inventory_transfers(source_establishment_id,status,created_at desc);
create index inventory_transfers_destination_status_idx on public.inventory_transfers(destination_establishment_id,status,created_at desc);

create or replace function central_production_private.service_only() returns void language plpgsql security definer set search_path='' as $$begin if current_setting('request.jwt.claim.role',true)<>'service_role' then raise exception 'internal only';end if;end$$;
create or replace function central_production_private.audit(org uuid,unit_id uuid,store uuid,event_name text,entity_name text,entity uuid,details jsonb default '{}') returns void language sql security definer set search_path='' as $$insert into public.production_audit_events(organization_id,production_unit_id,store_id,actor_user_id,event_type,entity_type,entity_id,metadata) values(org,unit_id,store,auth.uid(),event_name,entity_name,entity,coalesce(details,'{}'))$$;

create or replace function public.reserve_production_material(requested_order uuid,requested_item uuid,requested_lot uuid,requested_quantity numeric,requested_idempotency text) returns uuid language plpgsql security definer set search_path='' as $$declare o public.production_orders;u public.production_units;i public.inventory_items;l public.inventory_lots;r uuid;begin
 perform central_production_private.service_only();if requested_quantity<=0 then raise exception 'invalid quantity';end if;
 select * into o from public.production_orders where id=requested_order for update;if not found or o.status not in('draft','planned','released') then raise exception 'order unavailable';end if;
 select * into u from public.production_units where id=o.production_unit_id;select * into i from public.inventory_items where id=requested_item and establishment_id=u.inventory_establishment_id for update;
 if not found or i.balance-i.reserved_quantity<requested_quantity then raise exception 'insufficient material';end if;
 if requested_lot is not null then select * into l from public.inventory_lots where id=requested_lot and inventory_item_id=i.id for update;if not found or l.status not in('active','released') or l.quantity_available<requested_quantity then raise exception 'lot blocked, quarantined, expired or insufficient';end if;end if;
 insert into public.inventory_reservations(organization_id,establishment_id,inventory_item_id,lot_id,source_type,source_id,quantity,idempotency_key,created_by) values(o.organization_id,u.inventory_establishment_id,i.id,requested_lot,'production_order',o.id,requested_quantity,requested_idempotency,auth.uid()) on conflict(organization_id,idempotency_key) do update set updated_at=now() returning id into r;
 update public.inventory_items set reserved_quantity=reserved_quantity+requested_quantity,updated_at=now() where id=i.id;update public.production_material_requirements set reserved_quantity=reserved_quantity+requested_quantity,shortage_quantity=greatest(0,required_quantity-reserved_quantity-requested_quantity) where production_order_id=o.id and inventory_item_id=i.id;
 perform central_production_private.audit(o.organization_id,o.production_unit_id,u.inventory_establishment_id,'production.material_reserved','production_order',o.id,jsonb_build_object('item_id',i.id,'quantity',requested_quantity));return r;end$$;

create or replace function public.issue_production_material(requested_order uuid,requested_batch uuid,requested_item uuid,requested_lot uuid,requested_quantity numeric,requested_unit text,requested_idempotency text) returns uuid language plpgsql security definer set search_path='' as $$declare o public.production_orders;u public.production_units;i public.inventory_items;l public.inventory_lots;m uuid;issue_id uuid;begin
 perform central_production_private.service_only();if requested_quantity<=0 then raise exception 'invalid quantity';end if;select * into o from public.production_orders where id=requested_order for update;if not found or o.status not in('released','in_progress') then raise exception 'order not released';end if;select * into u from public.production_units where id=o.production_unit_id;select * into i from public.inventory_items where id=requested_item and establishment_id=u.inventory_establishment_id for update;select * into l from public.inventory_lots where id=requested_lot and inventory_item_id=i.id for update;
 if not found or l.status not in('active','released') then raise exception 'blocked or quarantined lot';end if;if i.balance<requested_quantity or l.quantity_available<requested_quantity then raise exception 'negative stock blocked';end if;
 update public.inventory_items set balance=balance-requested_quantity,reserved_quantity=greatest(0,reserved_quantity-requested_quantity),updated_at=now() where id=i.id returning balance into i.balance;update public.inventory_lots set quantity_available=quantity_available-requested_quantity,status=case when quantity_available-requested_quantity=0 then 'depleted' else status end,updated_at=now() where id=l.id;
 insert into public.inventory_movements(establishment_id,organization_id,stock_item_id,lot_id,production_batch_id,quantity,balance_after,kind,reason,actor_id,actor_name,unit_cost_cents,total_cost_cents,reference_type,reference_id,metadata) values(u.inventory_establishment_id,o.organization_id,i.id,l.id,requested_batch,-requested_quantity,i.balance,'production_out','Baixa oficial para produção',auth.uid(),'Central de produção',i.average_cost_cents,round(requested_quantity*i.average_cost_cents),'production_order',o.id,jsonb_build_object('idempotency_key',requested_idempotency)) returning id into m;
 insert into public.production_material_issues(organization_id,production_order_id,production_batch_id,inventory_item_id,lot_id,quantity,unit,inventory_movement_id,idempotency_key,issued_by) values(o.organization_id,o.id,requested_batch,i.id,l.id,requested_quantity,requested_unit,m,requested_idempotency,auth.uid()) returning id into issue_id;
 if requested_batch is not null then insert into public.production_batch_inputs(production_batch_id,inventory_item_id,lot_id,quantity_used,unit,inventory_movement_id,material_issue_id) values(requested_batch,i.id,l.id,requested_quantity,requested_unit,m,issue_id);end if;update public.production_material_requirements set issued_quantity=issued_quantity+requested_quantity where production_order_id=o.id and inventory_item_id=i.id;update public.production_orders set status='in_progress',started_at=coalesce(started_at,now()),updated_at=now() where id=o.id;return issue_id;end$$;

create or replace function public.complete_production_batch(requested_order uuid,requested_batch uuid,requested_actual_quantity numeric,requested_waste numeric,requested_expires_at timestamptz,requested_quality_status text,requested_cost jsonb,requested_idempotency text) returns jsonb language plpgsql security definer set search_path='' as $$declare o public.production_orders;u public.production_units;r public.production_recipe_profiles;i public.inventory_items;b public.production_batches;l uuid;m uuid;total bigint;per_unit numeric;lot_code text;begin
 perform central_production_private.service_only();if requested_actual_quantity<=0 then raise exception 'invalid output';end if;select * into o from public.production_orders where id=requested_order for update;select * into u from public.production_units where id=o.production_unit_id;select * into r from public.production_recipe_profiles where id=o.recipe_id;select * into i from public.inventory_items where id=r.output_item_id and establishment_id=u.inventory_establishment_id for update;select * into b from public.production_batches where id=requested_batch and production_order_id=o.id for update;if not found then raise exception 'batch unavailable';end if;if requested_quality_status not in('not_required','passed','warning','quarantined','released') then raise exception 'quality release required';end if;
 lot_code=coalesce(b.batch_number,'BAT-'||to_char(now(),'YYYYMMDD')||'-'||lpad((extract(epoch from clock_timestamp())::bigint%10000)::text,4,'0'));insert into public.inventory_lots(organization_id,store_id,inventory_item_id,internal_lot_code,manufactured_at,expiration_at,expiration_source,quantity_received,quantity_available,unit,status,unit_cost_cents,created_by) values(o.organization_id,u.inventory_establishment_id,i.id,lot_code,now(),requested_expires_at,'system_calculated',requested_actual_quantity,requested_actual_quantity,o.unit,case when requested_quality_status='quarantined' then 'quarantined' else 'released' end,coalesce((requested_cost->>'cost_per_unit_cents')::numeric,0),auth.uid()) returning id into l;
 update public.inventory_items set balance=balance+requested_actual_quantity,average_cost_cents=case when balance+requested_actual_quantity=0 then average_cost_cents else round(((balance*average_cost_cents)+(requested_actual_quantity*coalesce((requested_cost->>'cost_per_unit_cents')::numeric,0)))/(balance+requested_actual_quantity),4) end,last_cost_cents=coalesce((requested_cost->>'cost_per_unit_cents')::numeric,last_cost_cents),updated_at=now() where id=i.id returning balance into i.balance;
 insert into public.inventory_movements(establishment_id,organization_id,stock_item_id,lot_id,production_batch_id,quantity,balance_after,kind,reason,actor_id,actor_name,unit_cost_cents,total_cost_cents,reference_type,reference_id,metadata) values(u.inventory_establishment_id,o.organization_id,i.id,l,b.id,requested_actual_quantity,i.balance,'production_in','Entrada oficial de produção',auth.uid(),'Central de produção',coalesce((requested_cost->>'cost_per_unit_cents')::numeric,0),coalesce((requested_cost->>'total_cents')::bigint,0),'production_order',o.id,jsonb_build_object('idempotency_key',requested_idempotency)) returning id into m;
 total=coalesce((requested_cost->>'total_cents')::bigint,0);per_unit=coalesce((requested_cost->>'cost_per_unit_cents')::numeric,case when requested_actual_quantity>0 then total/requested_actual_quantity else 0 end);insert into public.production_cost_snapshots(organization_id,production_batch_id,material_cents,packaging_cents,direct_labor_estimate_cents,overhead_estimate_cents,total_cents,cost_per_unit_cents,components,locked_by) values(o.organization_id,b.id,coalesce((requested_cost->>'material_cents')::bigint,0),coalesce((requested_cost->>'packaging_cents')::bigint,0),coalesce((requested_cost->>'direct_labor_estimate_cents')::bigint,0),coalesce((requested_cost->>'overhead_estimate_cents')::bigint,0),total,per_unit,coalesce(requested_cost->'components','[]'),auth.uid());
 update public.production_batches set output_lot_id=l,quantity_produced=requested_actual_quantity,actual_quantity=requested_actual_quantity,actual_yield=requested_actual_quantity,expected_yield=r.expected_yield,yield_variance=requested_actual_quantity-r.expected_yield,waste_quantity=coalesce(requested_waste,0),quality_status=requested_quality_status,status=case when requested_quality_status='quarantined' then 'blocked' else 'completed' end,cost_snapshot=requested_cost,total_cost_cents=total,cost_per_unit_cents=per_unit,cost_locked_at=now() where id=b.id;update public.production_orders set actual_quantity=coalesce(actual_quantity,0)+requested_actual_quantity,status=case when coalesce(actual_quantity,0)+requested_actual_quantity>=planned_quantity then 'completed' else 'partially_completed' end,completed_at=case when coalesce(actual_quantity,0)+requested_actual_quantity>=planned_quantity then now() else completed_at end,updated_at=now() where id=o.id;return jsonb_build_object('batch_id',b.id,'lot_id',l,'movement_id',m,'cost_locked',true);end$$;

create or replace function public.dispatch_internal_transfer(requested_transfer uuid,requested_idempotency text) returns jsonb language plpgsql security definer set search_path='' as $$declare t public.inventory_transfers;line record;i public.inventory_items;l public.inventory_lots;loc uuid;m uuid;begin
 perform central_production_private.service_only();select * into t from public.inventory_transfers where id=requested_transfer for update;if not found or t.status not in('approved','picking','packed') then raise exception 'transfer unavailable';end if;perform pg_advisory_xact_lock(hashtextextended('inventory:'||t.organization_id::text,0));select id into loc from public.inventory_locations where organization_id=t.organization_id and store_id=t.source_establishment_id and location_type='in_transit' and active limit 1;if loc is null then insert into public.inventory_locations(organization_id,store_id,name,location_type) values(t.organization_id,t.source_establishment_id,'IN_TRANSIT','in_transit') returning id into loc;end if;
 for line in select tl.*,ti.source_item_id from public.inventory_transfer_item_lots tl join public.inventory_transfer_items ti on ti.id=tl.transfer_item_id where ti.transfer_id=t.id order by tl.id for update loop select * into i from public.inventory_items where id=line.source_item_id and establishment_id=t.source_establishment_id for update;select * into l from public.inventory_lots where id=line.source_lot_id and inventory_item_id=i.id for update;if l.status not in('active','released') then raise exception 'blocked or quarantined lot cannot transfer';end if;if i.balance<line.quantity_requested or l.quantity_available<line.quantity_requested then raise exception 'negative stock blocked';end if;update public.inventory_items set balance=balance-line.quantity_requested,updated_at=now() where id=i.id returning balance into i.balance;update public.inventory_lots set quantity_available=quantity_available-line.quantity_requested,status=case when quantity_available-line.quantity_requested=0 then 'depleted' else status end,updated_at=now() where id=l.id;insert into public.inventory_movements(establishment_id,organization_id,stock_item_id,lot_id,quantity,balance_after,kind,reason,actor_id,actor_name,unit_cost_cents,total_cost_cents,reference_type,reference_id,metadata) values(t.source_establishment_id,t.organization_id,i.id,l.id,-line.quantity_requested,i.balance,'transfer_out','Source Warehouse → In Transit',auth.uid(),'Transferência interna',i.average_cost_cents,round(line.quantity_requested*i.average_cost_cents),'inventory_transfer',t.id,jsonb_build_object('to_location_id',loc,'idempotency_key',requested_idempotency)) returning id into m;update public.inventory_transfer_item_lots set quantity_sent=line.quantity_requested where id=line.id;insert into public.inventory_transfer_transit_balances(organization_id,transfer_id,transfer_item_lot_id,inventory_item_id,lot_id,quantity,unit,location_id) values(t.organization_id,t.id,line.id,i.id,l.id,line.quantity_requested,line.unit,loc);end loop;update public.inventory_transfers set status='in_transit',dispatched_at=now(),sent_at=now(),sent_by=auth.uid(),in_transit_location_id=loc where id=t.id;return jsonb_build_object('transfer_id',t.id,'status','in_transit','location_id',loc);end$$;

create or replace function public.receive_internal_transfer(requested_transfer uuid,requested_lines jsonb,requested_idempotency text) returns jsonb language plpgsql security definer set search_path='' as $$declare t public.inventory_transfers;receipt uuid;entry jsonb;tl public.inventory_transfer_item_lots;ti public.inventory_transfer_items;transit public.inventory_transfer_transit_balances;dest public.inventory_items;source_lot public.inventory_lots;dest_lot uuid;m uuid;qty numeric;rejected numeric;result text;has_diff boolean:=false;begin
 perform central_production_private.service_only();select * into t from public.inventory_transfers where id=requested_transfer for update;if not found or t.status not in('in_transit','partially_received','discrepancy_review') then raise exception 'transfer not receivable';end if;insert into public.transfer_receipts(organization_id,transfer_id,destination_establishment_id,result,status,received_by,received_at,idempotency_key) values(t.organization_id,t.id,t.destination_establishment_id,'accepted','confirmed',auth.uid(),now(),requested_idempotency) returning id into receipt;
 for entry in select value from jsonb_array_elements(requested_lines) loop select * into tl from public.inventory_transfer_item_lots where id=(entry->>'transfer_item_lot_id')::uuid for update;select * into ti from public.inventory_transfer_items where id=tl.transfer_item_id and transfer_id=t.id;select * into transit from public.inventory_transfer_transit_balances where transfer_item_lot_id=tl.id for update;qty=coalesce((entry->>'quantity_received')::numeric,0);rejected=coalesce((entry->>'quantity_rejected')::numeric,0);if qty<0 or rejected<0 or qty+rejected>transit.quantity then raise exception 'invalid receipt quantity';end if;select * into dest from public.inventory_items where id=ti.destination_item_id and establishment_id=t.destination_establishment_id for update;if not found then raise exception 'destination item mapping required';end if;select * into source_lot from public.inventory_lots where id=tl.source_lot_id;if source_lot.status in('blocked','quarantined','expired','recalled','discarded') then raise exception 'lot became unavailable; quality review required';end if;select id into dest_lot from public.inventory_lots where store_id=t.destination_establishment_id and internal_lot_code=source_lot.internal_lot_code;if dest_lot is null then insert into public.inventory_lots(organization_id,store_id,inventory_item_id,parent_lot_id,internal_lot_code,manufactured_at,expiration_at,expiration_source,quantity_received,quantity_available,unit,status,unit_cost_cents,created_by) values(t.organization_id,t.destination_establishment_id,dest.id,source_lot.id,source_lot.internal_lot_code,source_lot.manufactured_at,source_lot.expiration_at,source_lot.expiration_source,qty,qty,coalesce(nullif(tl.unit,''),dest.unit),'released',source_lot.unit_cost_cents,auth.uid()) returning id into dest_lot;else update public.inventory_lots set quantity_received=quantity_received+qty,quantity_available=quantity_available+qty,updated_at=now() where id=dest_lot;end if;update public.inventory_items set balance=balance+qty,updated_at=now() where id=dest.id returning balance into dest.balance;insert into public.inventory_movements(establishment_id,organization_id,stock_item_id,lot_id,quantity,balance_after,kind,reason,actor_id,actor_name,unit_cost_cents,total_cost_cents,reference_type,reference_id,metadata) values(t.destination_establishment_id,t.organization_id,dest.id,dest_lot,qty,dest.balance,'transfer_in','In Transit → Destination Warehouse',auth.uid(),'Recebimento interno',source_lot.unit_cost_cents,round(qty*coalesce(source_lot.unit_cost_cents,0)),'inventory_transfer',t.id,jsonb_build_object('from_location_id',transit.location_id,'idempotency_key',requested_idempotency)) returning id into m;result=coalesce(entry->>'condition','accepted');insert into public.transfer_receipt_items(receipt_id,transfer_item_lot_id,quantity_received,quantity_rejected,condition,destination_movement_id,destination_lot_id) values(receipt,tl.id,qty,rejected,result,m,dest_lot);update public.inventory_transfer_item_lots set quantity_received=quantity_received+qty,quantity_rejected=quantity_rejected+rejected,destination_lot_id=dest_lot where id=tl.id;update public.inventory_transfer_transit_balances set quantity=quantity-qty-rejected,updated_at=now() where id=transit.id;if qty<>tl.quantity_sent or rejected>0 or result<>'accepted' then has_diff=true;insert into public.transfer_discrepancies(organization_id,transfer_id,inventory_item_id,lot_id,discrepancy_type,sent_quantity,received_quantity,difference,reason) values(t.organization_id,t.id,dest.id,source_lot.id,case when result in('damaged','expired','temperature_issue','wrong_item','wrong_lot') then result when qty<tl.quantity_sent then 'shortage' else 'excess' end,tl.quantity_sent,qty,qty-tl.quantity_sent,entry->>'reason');end if;end loop;
 update public.inventory_transfer_items ti2 set received_quantity=(select coalesce(sum(tl2.quantity_received),0) from public.inventory_transfer_item_lots tl2 where tl2.transfer_item_id=ti2.id),sent_quantity=(select coalesce(sum(tl2.quantity_sent),0) from public.inventory_transfer_item_lots tl2 where tl2.transfer_item_id=ti2.id) where ti2.transfer_id=t.id;update public.inventory_transfers set status=case when has_diff then 'discrepancy_review' when exists(select 1 from public.inventory_transfer_transit_balances x where x.transfer_id=t.id and x.quantity>0) then 'partially_received' else 'received' end,received_at=case when not exists(select 1 from public.inventory_transfer_transit_balances x where x.transfer_id=t.id and x.quantity>0) then now() else received_at end,received_by=auth.uid() where id=t.id;update public.transfer_receipts set result=case when has_diff then 'partial' else 'accepted' end where id=receipt;return jsonb_build_object('receipt_id',receipt,'discrepancy_review',has_diff);end$$;

create or replace function central_production_private.reject_cost_mutation() returns trigger language plpgsql set search_path='' as $$begin raise exception 'production cost snapshots are immutable';end$$;
create trigger production_cost_snapshots_immutable before update or delete on public.production_cost_snapshots for each row execute function central_production_private.reject_cost_mutation();

create or replace function public.claim_production_planning_runs(requested_limit integer default 5) returns setof public.production_planning_runs language plpgsql security definer set search_path='' as $$begin perform central_production_private.service_only();return query with claimed as(select id from public.production_planning_runs where status='queued' order by created_at for update skip locked limit least(greatest(requested_limit,1),25)) update public.production_planning_runs r set status='running',started_at=now() from claimed where r.id=claimed.id returning r.*;end$$;

do $$declare t text;begin foreach t in array array['production_units','production_recipe_profiles','production_recipe_outputs','production_batch_policies','production_orders','production_material_requirements','inventory_reservations','production_material_issues','production_batch_quality_checks','production_waste_records','production_cost_snapshots','internal_requisitions','internal_requisition_items','production_allocations','internal_supply_links','inventory_transfer_item_lots','transfer_packages','inventory_transfer_transit_balances','transfer_receipts','transfer_receipt_items','transfer_discrepancies','internal_transfer_returns','internal_transfer_return_items','production_planning_runs','production_audit_events','production_observability_hourly','central_production_member_permissions'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);execute format('create policy %I on public.%I for all to service_role using(true) with check(true)',t||'_service_only',t);end loop;end$$;
revoke all on function public.reserve_production_material(uuid,uuid,uuid,numeric,text),public.issue_production_material(uuid,uuid,uuid,uuid,numeric,text,text),public.complete_production_batch(uuid,uuid,numeric,numeric,timestamptz,text,jsonb,text),public.dispatch_internal_transfer(uuid,text),public.receive_internal_transfer(uuid,jsonb,text),public.claim_production_planning_runs(integer) from public,anon,authenticated;
grant execute on function public.reserve_production_material(uuid,uuid,uuid,numeric,text),public.issue_production_material(uuid,uuid,uuid,uuid,numeric,text,text),public.complete_production_batch(uuid,uuid,numeric,numeric,timestamptz,text,jsonb,text),public.dispatch_internal_transfer(uuid,text),public.receive_internal_transfer(uuid,jsonb,text),public.claim_production_planning_runs(integer) to service_role;

create or replace view public.fact_production_orders with(security_invoker=true) as select organization_id,production_unit_id,id production_order_id,recipe_id,status,source_type,planned_quantity,actual_quantity,unit,planned_start_at,started_at,completed_at,created_at from public.production_orders;
create or replace view public.fact_production_batches with(security_invoker=true) as select organization_id,id production_batch_id,production_order_id,output_item_id,output_lot_id,status,quality_status,expected_yield,actual_yield,yield_variance,waste_quantity,total_cost_cents,cost_per_unit_cents,production_date from public.production_batches;
create or replace view public.fact_production_material_usage with(security_invoker=true) as select organization_id,production_order_id,production_batch_id,inventory_item_id,lot_id,quantity,unit,issued_at from public.production_material_issues;
create or replace view public.fact_production_yield with(security_invoker=true) as select organization_id,id production_batch_id,production_order_id,expected_yield,actual_yield,yield_variance,waste_quantity,production_date from public.production_batches;
create or replace view public.fact_internal_requisitions with(security_invoker=true) as select organization_id,id requisition_id,requesting_store_id,supplying_unit_id,status,priority,requested_for_date,created_at from public.internal_requisitions;
create or replace view public.fact_internal_transfers with(security_invoker=true) as select organization_id,id transfer_id,source_establishment_id,destination_establishment_id,status,valuation_method,created_at,dispatched_at,received_at from public.inventory_transfers where fulfillment_type='internal_transfer';
create or replace view public.fact_transfer_receipts with(security_invoker=true) as select organization_id,id receipt_id,transfer_id,destination_establishment_id,result,status,received_at,created_at from public.transfer_receipts;
create or replace view public.fact_transfer_discrepancies with(security_invoker=true) as select organization_id,id discrepancy_id,transfer_id,inventory_item_id,lot_id,discrepancy_type,difference,status,created_at,resolved_at from public.transfer_discrepancies;
revoke all on public.fact_production_orders,public.fact_production_batches,public.fact_production_material_usage,public.fact_production_yield,public.fact_internal_requisitions,public.fact_internal_transfers,public.fact_transfer_receipts,public.fact_transfer_discrepancies from public,anon,authenticated;
grant select on public.fact_production_orders,public.fact_production_batches,public.fact_production_material_usage,public.fact_production_yield,public.fact_internal_requisitions,public.fact_internal_transfers,public.fact_transfer_receipts,public.fact_transfer_discrepancies to service_role;

insert into public.workspace_widget_registry(id,title,description,category,widget_type,size_options,required_permissions,supported_scopes,data_source,refresh_strategy,configuration_schema,default_settings,route,display_safe,sensitive) values
