insert into public.analytics_metric_catalog(metric_key,name,description,formula,source_of_truth,grain,owner_label,refresh_frequency,unit,evidence_class,certified,sensitive,allowed_dimensions) values
('production_plan_attainment','Production Plan Attainment','Produção real sobre produção planejada.','sum(actual_quantity) / nullif(sum(planned_quantity),0)','fact_production_orders','production_unit/period','Produção','hourly','percent','calculation',true,false,array['organization','production_unit','date','recipe']),
('production_yield','Production Yield','Rendimento real sobre esperado.','sum(actual_yield) / nullif(sum(expected_yield),0)','fact_production_yield','batch','Produção','hourly','percent','calculation',true,false,array['organization','production_unit','date','recipe']),
('production_waste_rate','Production Waste Rate','Desperdício registrado sobre produção.','sum(waste_quantity) / nullif(sum(actual_yield),0)','fact_production_yield','batch','Produção','hourly','percent','calculation',true,true,array['organization','production_unit','date','recipe']),
('requisition_fill_rate','Requisition Fill Rate','Quantidade atendida no prazo sobre quantidade aprovada.','fulfilled_on_time / nullif(approved_quantity,0)','fact_internal_requisitions','store/period','Abastecimento','hourly','percent','calculation',true,false,array['organization','store','production_unit','date']),
('on_time_transfer_rate','On-Time Transfer Rate','Transferências recebidas até a previsão.','received_on_time / nullif(received_transfers,0)','fact_internal_transfers','route/period','Logística interna','hourly','percent','calculation',true,false,array['organization','source','destination','date']),
('transfer_discrepancy_rate','Transfer Discrepancy Rate','Recebimentos com divergência sobre recebimentos.','discrepant_receipts / nullif(receipts,0)','fact_transfer_discrepancies','route/period','Logística interna','hourly','percent','calculation',true,true,array['organization','source','destination','date','type']),
('central_stock_coverage','Central Stock Coverage','Cobertura estimada do estoque central.','available_stock / forecast_daily_demand','inventory_items + forecast_predictions','item/unit/day','Estoque','hourly','days','estimate',true,true,array['organization','production_unit','item','date']),
('batch_hold_rate','Batch Hold Rate','Lotes retidos sobre lotes concluídos.','quality_hold_batches / nullif(completed_batches,0)','fact_production_batches','production_unit/period','Qualidade','hourly','percent','calculation',true,true,array['organization','production_unit','date','recipe']),
('average_production_lead_time','Average Production Lead Time','Tempo médio entre liberação e conclusão.','avg(completed_at-released_at)','fact_production_orders','production_unit/period','Produção','hourly','hours','calculation',true,false,array['organization','production_unit','date','recipe']),
('internal_transfer_lead_time','Internal Transfer Lead Time','Tempo médio entre despacho e recebimento.','avg(received_at-dispatched_at)','fact_internal_transfers','route/period','Logística interna','hourly','hours','calculation',true,false,array['organization','source','destination','date']),
('average_batch_cost','Average Batch Cost','Custo gerencial médio dos lotes fechados.','avg(total_cost_cents)','fact_production_batches','production_unit/period','Financeiro','daily','cents','calculation',true,true,array['organization','production_unit','date','recipe']),
('cost_per_produced_unit','Cost per Produced Unit','Custo gerencial médio por unidade produzida.','sum(total_cost_cents) / nullif(sum(actual_yield),0)','fact_production_batches','production_unit/period','Financeiro','daily','cents','calculation',true,true,array['organization','production_unit','date','recipe'])
on conflict(metric_key) do update set description=excluded.description,formula=excluded.formula,source_of_truth=excluded.source_of_truth,sensitive=excluded.sensitive;

